import{_ as t,o,c as a,a5 as d}from"./chunks/framework.CXroN2RO.js";const r="/study/images/browser/audio-comb-paths.svg",i="/study/images/browser/audio-comb-response.svg",b=JSON.parse('{"title":"Web Audioのコムフィルター — 遅延と干渉","description":"","frontmatter":{"title":"Web Audioのコムフィルター — 遅延と干渉","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"同じ音を二つの経路に分け、片方だけ遅らせて足すと、周波数によって強め合ったり打ち消し合ったりする。遅延時間とゲインから周波数応答を計算し、Web Audioの実測値と比べる。","aliases":["Web Audio API","コムフィルター","くし形フィルター","comb filter","DelayNode","フィードフォワード","位相差","干渉","インパルス応答","周波数応答"],"verification":"W3C Web Audio APIのDelayNodeとJulius O. SmithのPhysical Audio Signal Processingに照合（2026-11-06）"}},"headers":[],"relativePath":"browser/audio-comb-filter.md","filePath":"browser/audio-comb-filter.md"}'),s={name:"browser/audio-comb-filter.md"};function c(l,e,n,g,h,u){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="web-audioのコムフィルター-—-遅延と干渉" tabindex="-1">Web Audioのコムフィルター — 遅延と干渉 <a class="header-anchor" href="#web-audioのコムフィルター-—-遅延と干渉" aria-label="Permalink to &quot;Web Audioのコムフィルター — 遅延と干渉&quot;">​</a></h1><p>同じ音を二つの経路で鳴らし、片方だけを少し遅らせて足すと、周波数によって強め合ったり打ち消し合ったりします。周波数応答に山と谷が等間隔に並ぶため、この処理を<strong>コムフィルター</strong>（くし形フィルター）と呼びます。ミキシングでは二つの信号を同じ時刻に足します。ここではクロスフェードで扱った波形の重なり方が、遅延によって周波数ごとに変わります。<a href="/study/browser/audio-mixing-and-headroom.html">Web Audioのミキシングとヘッドルーム</a>、<a href="/study/browser/audio-crossfade.html">Web Audioのクロスフェード</a></p><h2 id="元の音と遅らせた音を足す" tabindex="-1">元の音と遅らせた音を足す <a class="header-anchor" href="#元の音と遅らせた音を足す" aria-label="Permalink to &quot;元の音と遅らせた音を足す&quot;">​</a></h2><p>一つの音源を、すぐに届く<strong>直接経路</strong>と、<code>DelayNode</code> で <code>T</code> 秒遅らせる<strong>遅延経路</strong>に分けます。サンプルレートを <code>Fs</code> とし、遅延が整数サンプル <code>D = T × Fs</code> に相当するとき、<code>x[n]</code> は現在の入力、<code>x[n − D]</code> は <code>D</code> サンプル前の入力です。遅延経路の振幅を直接経路の <code>g</code> 倍（ここでは <code>0 ≤ g ≤ 1</code>）にして、二つの経路のゲインの和を1にそろえます。<a href="https://www.w3.org/TR/webaudio-1.1/#DelayNode" target="_blank" rel="noreferrer">W3C Web Audio APIのDelayNode</a>、<a href="https://www.dsprelated.com/freebooks/pasp/Feedforward_Comb_Filters.html" target="_blank" rel="noreferrer">Julius O. Smithのフィードフォワード・コムフィルター</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y[n] = x[n] / (1 + g) + g × x[n − D] / (1 + g)</span></span></code></pre></div><p>Web Audioでは各経路に <code>GainNode</code> を置き、同じ後段ノードの入力へつなぐと出力が足し合わされます。<code>DelayNode</code> は入力を内部バッファに蓄え、設定した時間だけ前の位置から読み出します。例えば <code>g = 1</code>、<code>T = 2 ms</code>、<code>Fs = 48,000 Hz</code> で、先頭の1サンプルだけを <code>1</code> にすると、出力には振幅 <code>0.5</code> が0番と96番に現れます。この出力が<strong>インパルス応答</strong>です。出力を遅延の入力へ戻すフィードバック型では、このような短い入力からも繰り返しが生まれます。ここでは入力から出力に向かうフィードフォワード型を扱います。<a href="https://www.w3.org/TR/webaudio-1.1/#GainNode" target="_blank" rel="noreferrer">W3C Web Audio APIのGainNode</a>、<a href="https://www.w3.org/TR/webaudio-1.1/#channel-up-mixing-and-down-mixing" target="_blank" rel="noreferrer">チャンネルのミキシング</a>、<a href="https://www.dsprelated.com/freebooks/pasp/Feedback_Comb_Filters.html" target="_blank" rel="noreferrer">Julius O. Smithのフィードバック・コムフィルター</a></p><figure class="study-figure"><img src="'+r+'" alt="同じ音源を直接経路と遅延経路に分け、各経路のゲインを掛けてから足す。遅延2ミリ秒、サンプルレート48キロヘルツ、二つのゲインが同じ場合、インパルス応答は0番と96番の振幅0.5の2点になる。" width="760" height="640" loading="lazy"><figcaption>一つの短い入力を通すと、直接音と遅延音がいつ届くかを確認できます。<a href="/study/images/browser/audio-comb-paths.svg" target="_blank" rel="noopener noreferrer">経路とインパルス応答の図を拡大</a></figcaption></figure><h2 id="遅延時間で谷の位置が決まる" tabindex="-1">遅延時間で谷の位置が決まる <a class="header-anchor" href="#遅延時間で谷の位置が決まる" aria-label="Permalink to &quot;遅延時間で谷の位置が決まる&quot;">​</a></h2><p>一定時間の純粋な遅延だけなら、各周波数成分の振幅を保ったまま波形が時間方向にずれます。周波数 <code>f</code> Hz の正弦波を <code>T</code> 秒遅らせると、直接経路に対して位相が <code>2πfT</code> ラジアン遅れます。同じ <code>T = 2 ms</code> でも、250 Hzでは半周期ずれ、500 Hzではちょうど1周期ずれます。250 Hzでは山と谷がぶつかって振幅が小さくなり、500 Hzでは山同士と谷同士がそろいます。</p><p>二つを足したあとの振幅倍率は、直接経路の成分と、位相が遅れた成分のベクトルを足して求められます。分母でゲインの和を1にそろえているので、位相がそろう周波数での倍率は1（0 dB）です。0 Hzの一定入力（直流）も同じ倍率になります。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>|H(f)| = √(1 + g² + 2g × cos(2πfT)) / (1 + g)</span></span></code></pre></div><p><code>T &gt; 0</code>、<code>g &gt; 0</code> では、同じ位相で重なる <code>f = k / T</code> が山、半周期ずれて重なる <code>f = (k + 0.5) / T</code> が谷です。<code>k = 0, 1, 2, …</code> のうち、観測できる周波数の範囲を考えます。谷から次の谷までの間隔は <code>1 / T</code> です。<code>g = 1</code> なら谷で完全に打ち消し合います。<code>g = 0.5</code> なら谷にも振幅が <code>1/3</code> 残り、直流を基準に <code>20 × log10(1/3) ≈ −9.54 dB</code> です。<code>g = 0</code> では直接経路だけが残り、応答は平らになります。</p><table tabindex="0"><thead><tr><th style="text-align:right;">遅延時間 <code>T</code></th><th style="text-align:right;">最初の谷 <code>1 / (2T)</code></th><th style="text-align:right;">谷の間隔 <code>1 / T</code></th></tr></thead><tbody><tr><td style="text-align:right;">1 ms</td><td style="text-align:right;">500 Hz</td><td style="text-align:right;">1,000 Hz</td></tr><tr><td style="text-align:right;">2 ms</td><td style="text-align:right;">250 Hz</td><td style="text-align:right;">500 Hz</td></tr><tr><td style="text-align:right;">5 ms</td><td style="text-align:right;">100 Hz</td><td style="text-align:right;">200 Hz</td></tr><tr><td style="text-align:right;">10 ms</td><td style="text-align:right;">50 Hz</td><td style="text-align:right;">100 Hz</td></tr></tbody></table><figure class="study-figure"><img src="'+i+'" alt="0から1,000ヘルツの周波数応答。遅延2ミリ秒で谷は250と750ヘルツ。gが1の谷では完全に打ち消し合い、gが0.5の谷は約マイナス9.54デシベルに留まる。遅延5ミリ秒では谷が100ヘルツから200ヘルツ間隔で並ぶ。" width="760" height="670" loading="lazy"><figcaption>遅延時間を伸ばすと谷の間隔が狭くなります。遅延経路のゲインを下げると谷が浅くなります。<a href="/study/images/browser/audio-comb-response.svg" target="_blank" rel="noopener noreferrer">周波数応答の図を拡大</a></figcaption></figure><h2 id="ゲームで同じ音が別の経路から届く場面" tabindex="-1">ゲームで同じ音が別の経路から届く場面 <a class="header-anchor" href="#ゲームで同じ音が別の経路から届く場面" aria-label="Permalink to &quot;ゲームで同じ音が別の経路から届く場面&quot;">​</a></h2><p>壁の近くで足音が鳴る場面では、直接届く音に、少し長い距離を通って届く反射音が重なります。反射が1回だけで、反射音を一様に弱めると考えれば、この二経路のモデルに当てはまります。実際の壁は反射しやすさが周波数によって変わり、複数の面で反射します。<a href="https://www.dsprelated.com/freebooks/pasp/Feedforward_Comb_Filters.html" target="_blank" rel="noreferrer">Julius O. Smithのフィードフォワード・コムフィルター</a></p><p>同じ効果音を、直接出力する経路と、処理を通して出力する並列経路に分けたときも、片方に遅延があれば同じ干渉が起こります。処理した音を重ねたときだけ音色が変わるなら、各経路を単独で聴き、両方を通したときの時間差と周波数応答を調べると、遅延による干渉を切り分けられます。</p><h2 id="ブラウザで測って聴く" tabindex="-1">ブラウザで測って聴く <a class="header-anchor" href="#ブラウザで測って聴く" aria-label="Permalink to &quot;ブラウザで測って聴く&quot;">​</a></h2><p><a href="/study/practice/browser/audio-comb-observation.html">コムフィルターの実践</a>では、<code>OfflineAudioContext</code> で1サンプルの入力を二つの経路に通し、ブラウザの <code>DelayNode</code> を含むインパルス応答から周波数応答を求めます。まず遅延を2 ms、<code>g</code> を1にして最初の谷が250 Hz付近に出ることを確かめます。次に <code>g</code> を0.5にすると谷の位置が同じまま浅くなり、遅延を5 msにすると最初の谷が100 Hz付近に移ります。同じノイズを直接音と合成音で聴き比べると、応答に谷が並ぶときの音色の違いを確認できます。<a href="https://www.w3.org/TR/webaudio-1.1/#OfflineAudioContext" target="_blank" rel="noreferrer">W3C Web Audio APIのOfflineAudioContext</a></p><p>足し合わせた出力を遅延経路に戻すと、音が何度も繰り返されます。間隔と減衰の関係は、<a href="/study/browser/audio-feedback-delay.html">Web Audioのフィードバックディレイ</a>で確認できます。</p>',20)])])}const f=t(s,[["render",c]]);export{b as __pageData,f as default};
